12	function Fail([string]$Message) { throw "task-review-precheck: $Message" }
13	function Test-AdrBoundFilePath {
14	    param([string]$Root, [string]$Relative)
15	    if ($Relative -cnotmatch '^[A-Za-z0-9][A-Za-z0-9._/-]*$' -or
16	        $Relative.EndsWith('/', [StringComparison]::Ordinal) -or
17	        $Relative.Contains('//') -or $Relative -cmatch '(^|/)[.]{1,2}(/|$)') {
18	        return $false
19	    }
20	    $rootItem = Get-Item -LiteralPath $Root -Force -ErrorAction Stop
21	    if (-not $rootItem.PSIsContainer -or
22	        ($rootItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
23	        return $false
24	    }
25	    $current = $Root
26	    $components = $Relative.Split('/')
27	    for ($index = 0; $index -lt $components.Length; $index++) {
28	        $component = $components[$index]
29	        $matches = @(Get-ChildItem -LiteralPath $current -Force -ErrorAction Stop |
30	            Where-Object { [string]::Equals($_.Name, $component, [StringComparison]::Ordinal) })
31	        if ($matches.Count -ne 1) { return $false }
32	        $item = $matches[0]
33	        if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
34	            return $false
35	        }
36	        if ($index -lt $components.Length - 1) {
37	            if (-not $item.PSIsContainer) { return $false }
38	        }
39	        else {
40	            if ($item -isnot [IO.FileInfo] -or $item.PSIsContainer -or
41	                ($item.Attributes -band [IO.FileAttributes]::Device) -ne 0) {
42	                return $false
43	            }
44	            if (-not $IsWindows) {
45	                # FileInfo/Leaf also describe POSIX devices; require lstat type.
46	                $statProperty = $item.PSObject.Properties['UnixStat']
47	                if ($null -eq $statProperty -or $null -eq $statProperty.Value -or
48	                    -not [string]::Equals([string]$statProperty.Value.ItemType,
49	                        'File', [StringComparison]::Ordinal)) {
50	                    return $false
51	                }
52	            }
53	        }
54	        $current = $item.FullName
55	    }
56	    # The consuming hash/read must still fail closed on access/open failure.
57	    return $true
58	}
59	
60	# RT-20260908-004: the same restricted byte-oriented line grammar as Bash.
61	function Get-AdrDeclaredPaths {
62	    param([string]$DesignPath)
63	    # Latin-1 preserves each byte, including a BOM; the grammar is ASCII only.
64	    # ReadAllText would strip a BOM and diverge from LC_ALL=C awk at fences.
65	    $text = [Text.Encoding]::GetEncoding(28591).GetString([IO.File]::ReadAllBytes($DesignPath))
66	    $paths = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
67	    function Get-AdrRunWidth([string]$Line, [int]$Start, [char]$Delimiter) {
68	        $width = 0
69	        while (($Start + $width) -lt $Line.Length -and $Line[$Start + $width] -ceq $Delimiter) { $width++ }
70	        return $width
71	    }
72	    function Test-AdrRunEscaped([string]$Line, [int]$Start) {
73	        $slashes = 0
74	        while ($Start -gt 0 -and $Line[$Start - 1] -ceq [char]92) { $slashes++; $Start-- }
75	        return (($slashes % 2) -ne 0)
76	    }
77	    $fence = [char]0
78	    $fenceWidth = 0
79	    foreach ($rawLine in $text.Split([char]10)) {
80	        $line = $rawLine
81	        if ($line.Length -gt 0 -and $line[$line.Length - 1] -ceq [char]13) {
82	            $line = $line.Substring(0, $line.Length - 1)
83	        }
84	        $indent = 0
85	        while ($indent -lt $line.Length -and $line[$indent] -ceq [char]32) { $indent++ }
86	        $rest = $line.Substring($indent)
87	        $first = [char]0
88	        if ($rest.Length -gt 0) { $first = $rest[0] }
89	        if ($fence -cne [char]0) {
90	            if ($indent -le 3 -and $first -ceq $fence) {
91	                $width = Get-AdrRunWidth $rest 0 $fence
92	                if ($width -ge $fenceWidth -and $rest.Substring($width) -cmatch '^[ \t]*$') {
93	                    $fence = [char]0
94	                }
95	            }
96	            continue
97	        }
98	        if ($indent -ge 4 -or $first -ceq [char]9) { continue }
99	        if ($first -ceq [char]96 -or $first -ceq [char]126) {
100	            $width = Get-AdrRunWidth $rest 0 $first
101	            if ($width -ge 3) { $fence = $first; $fenceWidth = $width; continue }
102	        }
103	        $i = 0
104	        while ($i -lt $line.Length) {
105	            if ($line[$i] -cne [char]96) { $i++; continue }
106	            $width = Get-AdrRunWidth $line $i ([char]96)
107	            if (Test-AdrRunEscaped $line $i) { $i += $width; continue }
108	            $j = $i + $width
109	            $closed = $false
110	            while ($j -lt $line.Length) {
111	                if ($line[$j] -cne [char]96) { $j++; continue }
112	                $closeWidth = Get-AdrRunWidth $line $j ([char]96)
113	                if ($closeWidth -eq $width -and -not (Test-AdrRunEscaped $line $j)) {
114	                    $closed = $true
115	                    break
116	                }
117	                $j += $closeWidth
118	            }
119	            if (-not $closed) { break }
120	            $value = $line.Substring($i + $width, $j - $i - $width)
121	            if ($width -eq 1 -and $value -cmatch '^docs/adr/[0-9]{4}-[a-z0-9][a-z0-9-]*[.]md$') {
122	                [void]$paths.Add($value)
123	            }
124	            $i = $j + $width
125	        }
126	    }
127	    [string[]]$result = @($paths)
128	    [Array]::Sort($result, [StringComparer]::Ordinal)
129	    return $result
130	}
131	# Return JSON as a scalar to preserve both empty and singleton arrays.
132	function Get-AdrPrecheckInputsJson {
133	    param([string]$Root, [string]$DesignRelative, [string]$ExpectedDesign)
134	    if ($ExpectedDesign -cnotmatch '^[0-9a-f]{64}$' -or
135	        -not (Test-AdrBoundFilePath $Root $DesignRelative)) {
136	        Fail 'unsafe design ADR authority'
137	    }
138	    $designPath = Join-Path $Root $DesignRelative
139	    $before = (Get-FileHash -LiteralPath $designPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToLowerInvariant()
140	    if ($before -cne $ExpectedDesign) { Fail 'design changed before ADR collection' }
141	    $entries = [Collections.Generic.List[object]]::new()
142	    foreach ($path in @(Get-AdrDeclaredPaths $designPath)) {
143	        if (-not (Test-AdrBoundFilePath $Root $path)) { Fail "unsafe ADR input: $path" }
144	        $digest = (Get-FileHash -LiteralPath (Join-Path $Root $path) -Algorithm SHA256 -ErrorAction Stop).Hash.ToLowerInvariant()
145	        if ($digest -cnotmatch '^[0-9a-f]{64}$') { Fail 'invalid ADR digest' }
146	        $entries.Add([ordered]@{path=$path;sha256=$digest})
147	    }
148	    if (-not (Test-AdrBoundFilePath $Root $DesignRelative)) { Fail 'design path changed during collection' }
149	    $after = (Get-FileHash -LiteralPath $designPath -Algorithm SHA256 -ErrorAction Stop).Hash.ToLowerInvariant()
150	    if ($after -cne $ExpectedDesign) { Fail 'design changed during ADR collection' }
151	    return ConvertTo-Json -InputObject ($entries.ToArray()) -Depth 4 -Compress
152	}
153	# Only extension material uses this canonical order; legacy evidence is untouched.
154	function Get-AdrLayerJson {
155	    param($Layers)
156	    if ($null -eq $Layers -or ($Layers -isnot [pscustomobject] -and
157	        $Layers -isnot [Collections.IDictionary])) { Fail 'invalid layer object' }
158	    $names = if ($Layers -is [Collections.IDictionary]) { @($Layers.Keys) }
159	             else { @($Layers.PSObject.Properties.Name) }
160	    $expected = @('frontend-spec.md','infra-spec.md','security-spec.md','ux-spec.md')
161	    if ($names.Count -ne 0 -and $names.Count -ne 4) { Fail 'invalid layer key count' }
162	    foreach ($name in $names) {
163	        if ($name -isnot [string] -or $expected -cnotcontains $name) { Fail 'invalid layer key' }
164	    }
165	    $canonical = [ordered]@{}
166	    if ($names.Count -gt 0) {
167	        foreach ($name in $expected) {
168	            if ($names -cnotcontains $name) { Fail 'missing layer key' }
169	            $value = if ($Layers -is [Collections.IDictionary]) { $Layers[$name] }
170	                     else { $Layers.PSObject.Properties[$name].Value }
171	            if ($value -isnot [string] -or $value.Length -ne 64 -or $value -cnotmatch '^[0-9a-f]{64}$') {
172	                Fail 'invalid layer digest'
173	            }
174	            $canonical[$name] = $value
175	        }
176	    }
177	    return ConvertTo-Json -InputObject $canonical -Compress
178	}
179	
180	# Current PASS predecessor only; not historical NEEDS_WORK progress validation.
181	function Get-PersistedAdrJson {
182	  param($Entries)
183	  if ($Entries -isnot [array]) { Fail 'invalid persisted ADR array' }
184	  $normalized = [Collections.Generic.List[object]]::new()
185	  $previous = $null
186	  foreach ($entry in $Entries) {
187	    if ($null -eq $entry -or $entry -isnot [pscustomobject]) { Fail 'invalid persisted ADR entry' }
188	    $keys = @($entry.PSObject.Properties.Name)
189	    if ($keys.Count -ne 2 -or $keys -cnotcontains 'path' -or $keys -cnotcontains 'sha256' -or
190	        $entry.path -isnot [string] -or $entry.sha256 -isnot [string] -or
191	        $entry.path -cnotmatch '\Adocs/adr/[0-9]{4}-[a-z0-9][a-z0-9-]*[.]md\z' -or
192	        $entry.sha256.Length -ne 64 -or $entry.sha256 -cnotmatch '\A[0-9a-f]{64}\z') {
193	      Fail 'invalid persisted ADR fields'
194	    }
195	    if ($null -ne $previous -and [StringComparer]::Ordinal.Compare($previous, $entry.path) -ge 0) {
196	      Fail 'persisted ADR entries must be sorted and unique'
197	    }
198	    $previous = $entry.path
199	    $normalized.Add([ordered]@{path=$entry.path;sha256=$entry.sha256})
200	  }
201	  return ConvertTo-Json -InputObject ($normalized.ToArray()) -Compress -Depth 4
202	}
203	function Get-PersistedAdrPassPaths {
204	  param([string]$RepoRoot, $Contract, [string]$FeatureName,
205	        [string]$DesignReviewedHash, [string]$DesignCurrentHash)
206	  $relativeRoot = "reports/impl-review/$FeatureName/attempt-$($Contract.attempt)/round-$($Contract.round)"
207	  $precheckRelative = "$relativeRoot/precheck-result.json"
208	  $designRelative = "specs/$FeatureName/design.md"
209	  if (-not (Test-AdrBoundFilePath $RepoRoot "$relativeRoot/impl-review-contract.json") -or
210	      -not (Test-AdrBoundFilePath $RepoRoot $precheckRelative)) { Fail 'unsafe persisted ADR contract/precheck' }
211	  $precheckPath = Join-Path $RepoRoot $precheckRelative
212	  $precheckHash = (Get-FileHash -LiteralPath $precheckPath -Algorithm SHA256).Hash.ToLowerInvariant()
213	  $precheck = Get-Content -LiteralPath $precheckPath -Raw | ConvertFrom-Json -NoEnumerate
214	  if ($precheck -isnot [pscustomobject]) { Fail 'persisted ADR precheck must be an object' }
215	  $contractHasAdr = @($Contract.PSObject.Properties.Name) -ccontains 'adr_inputs'
216	  $precheckHasAdr = @($precheck.PSObject.Properties.Name) -ccontains 'adr_inputs'
217	  if ($contractHasAdr -ne $precheckHasAdr) { Fail 'one-sided persisted ADR extension' }
218	  if (-not $contractHasAdr) { return }
219	  if ($precheck.schema -cne 'impl-review-precheck/v1' -or $precheck.feature -cne $FeatureName -or
220	      $precheck.attempt -isnot [long] -or $precheck.round -isnot [long] -or
221	      $precheck.attempt -ne $Contract.attempt -or $precheck.round -ne $Contract.round) {
222	    Fail 'persisted ADR precheck identity mismatch'
223	  }
224	  $recorded = Get-PersistedAdrJson $precheck.adr_inputs
225	  if ((Get-PersistedAdrJson $Contract.adr_inputs) -cne $recorded) { Fail 'persisted ADR sets disagree' }
226	  foreach ($field in @('design_sha256','requirements_sha256','acceptance_sha256')) {
227	    if ($precheck.$field -isnot [string] -or $precheck.$field.Length -ne 64 -or
228	        $precheck.$field -cnotmatch '\A[0-9a-f]{64}\z' -or
229	        $Contract.$field -isnot [string] -or $Contract.$field -cne $precheck.$field) {
230	      Fail 'persisted ADR core pins disagree'
231	    }
232	  }
233	  $layers = Get-AdrLayerJson $precheck.layer_sha256
234	  if ((Get-AdrLayerJson $Contract.layer_sha256) -cne $layers) { Fail 'persisted ADR layer pins disagree' }
235	  foreach ($reviewer in $Contract.reviewers) {
236	    $letter = switch -CaseSensitive ($reviewer.role) { 'impl-reviewer-a' { 'a' } 'impl-reviewer-b' { 'b' } default { Fail 'invalid persisted ADR reviewer role' } }
237	    $outputRelative = "$relativeRoot/reviewer-$letter.json"
238	    if (-not (Test-AdrBoundFilePath $RepoRoot $outputRelative)) { Fail 'unsafe persisted ADR reviewer output' }
239	    $output = Get-Content -LiteralPath (Join-Path $RepoRoot $outputRelative) -Raw | ConvertFrom-Json -NoEnumerate
240	    if ($output -isnot [pscustomobject] -or $output.schema -cne "$($reviewer.role)/v1" -or
241	        $output.stage -cne 'impl' -or $output.role -cne $reviewer.role) { Fail 'persisted ADR output identity mismatch' }
242	    foreach ($field in @('run_id','host_session_id')) {
243	      if ($output.$field -isnot [string] -or [string]::IsNullOrWhiteSpace($output.$field) -or
244	          $output.$field -cne $reviewer.$field) { Fail 'persisted ADR output provenance mismatch' }
245	    }
246	    $manifests = @()
247	    foreach ($source in @($reviewer, $output)) {
248	      if ($source.allowed_input_manifest -isnot [array]) { Fail 'invalid persisted ADR output manifest' }
249	      $map = [Collections.Generic.SortedDictionary[string,string]]::new([StringComparer]::Ordinal)
250	      foreach ($entry in $source.allowed_input_manifest) {
251	        if ($entry.path -isnot [string] -or $entry.sha256 -isnot [string]) { Fail 'invalid persisted ADR output pin' }
252	        $relative = Get-ManifestRelativePath $entry.path $RepoRoot
253	        if ($null -eq $relative -or $map.ContainsKey($relative)) { Fail 'invalid or duplicate persisted ADR output path' }
254	        if ($relative.StartsWith('docs/adr/', [StringComparison]::Ordinal) -and $entry.path -cne $relative) { Fail 'ADR output path must be raw canonical relative' }
255	        $map.Add($relative, $entry.sha256)
256	      }
257	      $canonical = @($map.Keys | ForEach-Object { [ordered]@{path=$_;sha256=$map[$_]} })
258	      $manifests += ConvertTo-Json -InputObject $canonical -Compress -Depth 4
259	    }
260	    if ($manifests[0] -cne $manifests[1]) { Fail 'persisted ADR output manifest differs from reservation' }
261	    # The checks below bind the now-identical reservation and output to the precheck.
262	    $entries = @($reviewer.allowed_input_manifest)
263	    $documentPins = [ordered]@{
264	      'requirements.md' = $precheck.requirements_sha256
265	      'acceptance-tests.md' = $precheck.acceptance_sha256
266	    }
267	    foreach ($layer in $precheck.layer_sha256.PSObject.Properties) { $documentPins[$layer.Name] = $layer.Value }
268	    foreach ($document in $documentPins.Keys) {
269	      $expectedPath = "specs/$FeatureName/$document"
270	      $pins = @($entries | Where-Object { $_.path -is [string] -and (Get-ManifestRelativePath $_.path $RepoRoot) -ceq $expectedPath })
271	      if ($pins.Count -ne 1 -or $pins[0].sha256 -isnot [string] -or $pins[0].sha256 -cne $documentPins[$document]) {
272	        Fail "persisted ADR reviewer document binding mismatch: $document"
273	      }
274	    }
275	    $pcPins = @($entries | Where-Object { $_.path -is [string] -and (Get-ManifestRelativePath $_.path $RepoRoot) -ceq $precheckRelative })
276	    $designPins = @($entries | Where-Object { $_.path -is [string] -and (Get-ManifestRelativePath $_.path $RepoRoot) -ceq $designRelative })
277	    if ($pcPins.Count -ne 1 -or $pcPins[0].sha256 -cne $precheckHash -or
278	        $designPins.Count -ne 1 -or $designPins[0].sha256 -cne $precheck.design_sha256) {
279	      Fail 'reviewer lacks exact persisted ADR precheck/design binding'
280	    }
281	    $adrMap = [Collections.Generic.SortedDictionary[string,object]]::new([StringComparer]::Ordinal)
282	    foreach ($entry in $entries) {
283	      if ($entry.path -isnot [string]) { Fail 'invalid reviewer manifest path type' }
284	      if (-not $entry.path.StartsWith('docs/adr/', [StringComparison]::Ordinal)) { continue }
285	      if ($adrMap.ContainsKey($entry.path)) { Fail 'duplicate reviewer ADR entry' }
286	      $adrMap.Add($entry.path, [pscustomobject]@{path=$entry.path;sha256=$entry.sha256})
287	    }
288	    if ((Get-PersistedAdrJson @($adrMap.Values)) -cne $recorded) { Fail 'incomplete reviewer ADR set' }
289	  }
290	  if ($precheck.design_sha256 -cne $DesignReviewedHash -and
291	      $precheck.design_sha256 -cne $DesignCurrentHash) { Fail 'persisted ADR design changed beyond lifecycle fields' }
292	  $actual = Get-AdrPrecheckInputsJson $RepoRoot $designRelative $DesignCurrentHash
293	  if ($actual -cne $recorded) { Fail 'current design-derived ADR inputs differ from review' }
294	  $material = "$($precheck.design_sha256):$($precheck.requirements_sha256):$($precheck.acceptance_sha256)"
295	  if ($layers -cne '{}') { $material += ':' + $layers }
296	  $material += ':adr_inputs/v1:' + $recorded
297	  $inputHash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($material))).ToLowerInvariant()
298	  if ($precheck.input_sha256 -isnot [string] -or $precheck.input_sha256 -cne $inputHash) {
299	    Fail 'persisted ADR input hash mismatch'
300	  }
301	  if (-not (Test-AdrBoundFilePath $RepoRoot $precheckRelative) -or
302	      (Get-FileHash -LiteralPath $precheckPath -Algorithm SHA256).Hash.ToLowerInvariant() -cne $precheckHash) {
303	    Fail 'persisted ADR precheck changed during validation'
304	  }
305	  foreach ($entry in $precheck.adr_inputs) { $entry.path }
306	}
307	function Test-OrdinalEqual([object]$Left, [object]$Right) {
308	  return [string]::Equals([string]$Left, [string]$Right, [StringComparison]::Ordinal)
309	}
310	# WFI-025: the STATUS-NORMALIZED task-plan digest -- the same recipe as
311	# check-workflow-state.ps1 Get-NormalizedHash for the task stage (canonical
312	# form 1), which the accepting side already admits. Recorded instead of the
313	# raw digest when the plan's statuses are mixed, so the binding survives the
314	# lifecycle transitions the workflow is supposed to perform.
315	function Get-TasksNormalizedHash([string]$Path) {
316	  $text = [IO.File]::ReadAllText($Path)
317	  $text = [regex]::Replace($text, "(?m)^Task-Review-Status:[^\r\n]*(\r?)$", 'Task-Review-Status: Pending$1')
318	  $text = [regex]::Replace($text, "(?m)^Approval:[^\r\n]*(\r?)$", 'Approval: Draft$1')
319	  $text = [regex]::Replace($text, "(?m)^Status:[^\r\n]*(\r?)$", 'Status: Planned$1')
320	  $text = [regex]::Replace($text, "(?m)^Second Approval:[^\r\n]*\r?\n?", '')
321	  return [Convert]::ToHexString(
322	    [Security.Cryptography.SHA256]::HashData([Text.UTF8Encoding]::new($false).GetBytes($text))
323	  ).ToLower()
324	}
325	# WFI-025: uniform = every ^Status: line carries one value (or none exist).
326	# Uniqueness is ORDINAL (case-sensitive): Sort-Object -Unique folds case by
327	# default, which would classify a Done/done plan as uniform here while the
328	# sh twin's LC_ALL=C sort -u calls it mixed (PR #336 review; the AGENTS.md
329	# case-sensitivity sweep's cmdlet layer).
330	function Test-TasksStatusesMixed([string]$Path) {
331	  $values = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
332	  foreach ($line in [IO.File]::ReadAllLines($Path)) {
333	    $m = [regex]::Match($line, '^Status:[ \t]*(.*?)[ \t]*$')
334	    if ($m.Success) { [void]$values.Add($m.Groups[1].Value) }
335	  }
336	  return $values.Count -gt 1
337	}
338	function Get-ManifestRelativePath([string]$Path, [string]$RepoRoot) {
339	  $normalizedPath = $Path.Replace('\', '/')
340	  $normalizedRoot = $RepoRoot.Replace('\', '/').TrimEnd('/')
341	  if ($normalizedPath.StartsWith("$normalizedRoot/", [StringComparison]::Ordinal)) {
342	    $normalizedPath = $normalizedPath.Substring($normalizedRoot.Length + 1)
343	  } elseif ([IO.Path]::IsPathRooted($Path) -or $normalizedPath -match '^[A-Za-z]:/') {
344	    # Contracts persisted by predecessor gates record absolute paths of the
345	    # checkout that generated them. Relativize against the known repository
346	    # anchors so evidence stays verifiable from any checkout (issue #61).
347	    $anchorMatch = [Text.RegularExpressions.Regex]::Match(
348	      $normalizedPath, '^.*/(?<tail>(specs|reports|plugins)/.+)$')
349	    if (-not $anchorMatch.Success) { return $null }
350	    $normalizedPath = $anchorMatch.Groups['tail'].Value
351	  }
352	  if ($normalizedPath -match '(^|/)\.\.?(/|$)') { return $null }
353	  return $normalizedPath
354	}
355	# A round's verdict belongs to the text its two reviewers actually read: the
356	# two reviewers must have pinned the same hash for each reviewed document, and
357	# the contract must record that hash and no other. Mirrors
358	# lib/review-precheck-common.sh assert_contract_reviewer_agreement; the gap it
359	# closes (a contract recording a hash neither reviewer read) surfaced on
360	# epic-136-phase4-docs attempt 2 round 2.
361	function Assert-ContractReviewerAgreement([object]$Contract, [string]$Stage, [string]$FeatureName, [string]$RepoRoot) {
362	  $docKeys = @{ 'requirements.md' = 'requirements_sha256'; 'acceptance-tests.md' = 'acceptance_sha256'; 'design.md' = 'design_sha256' }
363	  foreach ($doc in @('requirements.md', 'acceptance-tests.md', 'design.md')) {
364	    $target = "specs/$FeatureName/$doc"
365	    $pinned = @{}
366	    foreach ($suffix in @('a', 'b')) {
367	      $role = "$Stage-reviewer-$suffix"
368	      $entries = @($Contract.reviewers |
369	        Where-Object { Test-OrdinalEqual $_.role $role } |
370	        ForEach-Object { $_.allowed_input_manifest } |
371	        Where-Object { Test-OrdinalEqual (Get-ManifestRelativePath ([string]$_.path) $RepoRoot) $target })
372	      $pinned[$suffix] = if ($entries.Count -ge 1) { [string]$entries[0].sha256 } else { '' }
373	    }
374	    if (-not $pinned['a'] -or -not $pinned['b']) { continue }
375	    if (-not (Test-OrdinalEqual $pinned['a'] $pinned['b'])) {
376	      Fail "persisted $Stage contract: reviewer-a and reviewer-b pinned different ${doc}; they did not review the same text"
377	    }
378	    $keyProp = $Contract.PSObject.Properties[$docKeys[$doc]]
379	    $contractHash = if ($null -ne $keyProp -and $null -ne $keyProp.Value) { [string]$keyProp.Value } else { '' }
380	    if ($contractHash -and -not (Test-OrdinalEqual $contractHash $pinned['a'])) {
381	      Fail "persisted $Stage contract records a ${doc} hash neither reviewer read; the verdict does not belong to that text"
382	    }
383	  }
384	}
385	function Test-AllowedManifestPath(
386	  [string]$Role,
387	  [string]$Path,
388	  [string]$Stage,
389	  [string]$FeatureName,
390	  [int]$Attempt,
391	  [int]$Round,
392	  [string]$CalibrationPath
393	) {
394	  $roleA = "$Stage-reviewer-a"
395	  $roleB = "$Stage-reviewer-b"
396	  $attemptRoot = "reports/$Stage-review/$FeatureName/attempt-$Attempt"
397	  $roundRoot = "$attemptRoot/round-$Round"
398	  $allowed = @(
399	    "specs/$FeatureName/requirements.md",
400	    "specs/$FeatureName/acceptance-tests.md",
401	    $CalibrationPath,
402	    "$roundRoot/precheck-result.json"
403	  )
404	  if (Test-OrdinalEqual $Stage 'spec') {
405	    $allowed += "specs/$FeatureName/investigation.md"
406	    if (Test-OrdinalEqual $Role $roleB) { $allowed += "$roundRoot/integrated-summary.json" }
407	  } elseif (Test-OrdinalEqual $Stage 'impl') {
408	    $allowed += "specs/$FeatureName/design.md", "specs/$FeatureName/investigation.md",
409	      "specs/$FeatureName/ux-spec.md", "specs/$FeatureName/frontend-spec.md",
410	      "specs/$FeatureName/infra-spec.md", "specs/$FeatureName/security-spec.md"
411	    if (Test-OrdinalEqual $Role $roleB) { $allowed += "$roundRoot/integrated-summary.json" }
412	    if ((Test-OrdinalEqual $Role $roleA) -and $Round -gt 1) {
413	      $allowed += "$attemptRoot/round-$($Round - 1)/integrated-summary.json"
414	    }
415	  } elseif (Test-OrdinalEqual $Stage 'task') {
416	    $allowed += "specs/$FeatureName/tasks.md", "specs/$FeatureName/design.md",
417	      "specs/$FeatureName/traceability.md",
418	      "specs/$FeatureName/ux-spec.md", "specs/$FeatureName/frontend-spec.md",
419	      "specs/$FeatureName/infra-spec.md", "specs/$FeatureName/security-spec.md"
420	    if (Test-OrdinalEqual $Role $roleA) { $allowed += "$roundRoot/dependency-graph.json" }
421	    if (Test-OrdinalEqual $Role $roleB) {
422	      $allowed += "$roundRoot/integrated-summary.json",
423	        'plugins/sdd-quality-loop/references/risk-gate-matrix.md',
424	        'plugins/sdd-quality-loop/references/risk-classification-policy.md'
425	    }
426	  }
427	  $validRole = (Test-OrdinalEqual $Role $roleA) -or (Test-OrdinalEqual $Role $roleB)
428	  $validPath = @($allowed | Where-Object { Test-OrdinalEqual $_ $Path }).Count -gt 0
429	  return $validRole -and $validPath
430	}
431	function Require-Pass(
432	  [string]$Root,
433	  [string]$Stage,
434	  [string]$FeatureName,
435	  [string]$RequirementsHash,
436	  [string]$AcceptanceHash,
437	  [string]$DesignHash,
438	  [string]$RequirementsCurrentHash,
439	  [string]$DesignCurrentHash
440	) {
441	  $repoRoot = (Resolve-Path (Join-Path $PSScriptRoot '../../..')).Path
442	  if (-not (Test-Path -LiteralPath $Root -PathType Container) -or (Get-Item -LiteralPath $Root).LinkType) { Fail "missing $Stage predecessor report root" }
443	  $verdictCandidates = @(Get-ChildItem -LiteralPath $Root -Filter integrated-verdict.json -File -Recurse)
444	  if ($verdictCandidates.Count -eq 0) { Fail "missing persisted $Stage PASS verdict" }
445	  $canonicalCandidates = foreach ($candidate in $verdictCandidates) {
446	    $relativeDirectory = [IO.Path]::GetRelativePath($Root, $candidate.DirectoryName).Replace('\', '/')
447	    $match = [Text.RegularExpressions.Regex]::Match($relativeDirectory, '^attempt-([1-9][0-9]*)/round-([1-9][0-9]*)$')
448	    if (-not $match.Success) { Fail "persisted $Stage verdict is outside a canonical attempt/round directory" }
449	    [pscustomobject]@{ File = $candidate; Attempt = [int64]$match.Groups[1].Value; Round = [int64]$match.Groups[2].Value }
450	  }
451	  $verdict = ($canonicalCandidates | Sort-Object Attempt, Round | Select-Object -Last 1).File
452	  $data = Get-Content -LiteralPath $verdict.FullName -Raw | ConvertFrom-Json
453	  $validVerdict = (Test-OrdinalEqual $data.feature $FeatureName) -and (Test-OrdinalEqual $data.stage $Stage) -and (Test-OrdinalEqual $data.verdict 'PASS') -and $data.attempt -gt 0 -and $data.round -gt 0
454	  if (Test-OrdinalEqual $Stage 'spec') { $validVerdict = $validVerdict -and (Test-OrdinalEqual $data.schema 'spec-review-integrated-verdict/v1') -and -not [string]::IsNullOrWhiteSpace($data.reviewer_a_run_id) -and -not [string]::IsNullOrWhiteSpace($data.reviewer_b_run_id) -and -not (Test-OrdinalEqual $data.reviewer_a_run_id $data.reviewer_b_run_id) -and -not [string]::IsNullOrWhiteSpace($data.reviewer_a_host_session_id) -and -not [string]::IsNullOrWhiteSpace($data.reviewer_b_host_session_id) -and -not (Test-OrdinalEqual $data.reviewer_a_host_session_id $data.reviewer_b_host_session_id) } else { $validVerdict = $validVerdict -and (Test-OrdinalEqual $data.schema 'integrated-verdict/v1') -and -not [string]::IsNullOrWhiteSpace($data.run_id) }
455	  if (-not $validVerdict) { Fail "persisted $Stage verdict is not a complete PASS contract" }
456	  $contractPath = Join-Path $verdict.DirectoryName "$Stage-review-contract.json"
457	  if (-not (Test-Path -LiteralPath $contractPath -PathType Leaf) -or (Get-Item -LiteralPath $contractPath).LinkType) { Fail "missing persisted $Stage review contract" }
458	  $contract = Get-Content -LiteralPath $contractPath -Raw | ConvertFrom-Json
459	  if (-not (Test-OrdinalEqual $contract.schema "$Stage-review-contract/v1") -or -not (Test-OrdinalEqual $contract.stage $Stage) -or -not (Test-OrdinalEqual $contract.feature $FeatureName) -or -not (Test-OrdinalEqual $contract.verdict 'PASS') -or $contract.attempt -le 0 -or $contract.round -le 0 -or [string]::IsNullOrWhiteSpace($contract.run_id)) { Fail "persisted $Stage contract is incomplete" }
460	  $expectedContractDirectory = [IO.Path]::GetFullPath((Join-Path $Root "attempt-$($contract.attempt)/round-$($contract.round)"))
461	  if (-not (Test-OrdinalEqual ([IO.Path]::GetFullPath($verdict.DirectoryName)) $expectedContractDirectory)) { Fail "persisted $Stage contract attempt/round do not match its report path" }
462	  $reviewers = @($contract.reviewers); $expectedRoles = @("$Stage-reviewer-a", "$Stage-reviewer-b")
463	  if ($reviewers.Count -ne 2 -or @($expectedRoles | Where-Object { $expectedRole = $_; @($reviewers | Where-Object { Test-OrdinalEqual $_.role $expectedRole }).Count -ne 1 }).Count -gt 0) { Fail "persisted $Stage contract has invalid reviewers" }
464	  if (@($reviewers.host_session_id | Where-Object { [string]::IsNullOrWhiteSpace($_) }).Count -gt 0 -or @($reviewers.host_session_id | Select-Object -Unique).Count -ne 2) { Fail "persisted $Stage contract does not isolate reviewer sessions" }
465	  if (@($reviewers.run_id | Where-Object { [string]::IsNullOrWhiteSpace($_) }).Count -gt 0 -or @($reviewers.run_id | Select-Object -Unique).Count -ne 2) { Fail "persisted $Stage contract has invalid reviewer run IDs" }
466	  $verifiedAdrPaths = @()
467	  if (Test-OrdinalEqual $Stage 'impl') {
468	    $verifiedAdrPaths = @(Get-PersistedAdrPassPaths $repoRoot $contract $FeatureName $DesignHash $DesignCurrentHash)
469	  }
470	  $manifest = @($reviewers | ForEach-Object { @($_.allowed_input_manifest) })
471	  $calibrationPath = if ($Stage -eq 'spec') { 'plugins/sdd-review-loop/references/spec-review-calibration.md' } else { 'plugins/sdd-review-loop/references/reviewer-calibration.md' }
472	  $calibrationHash = (Get-FileHash -LiteralPath (Join-Path $repoRoot $calibrationPath) -Algorithm SHA256).Hash.ToLower()
473	  $invalidManifest = @($reviewers | ForEach-Object {
474	    $role = $_.role
475	    @($_.allowed_input_manifest) | Where-Object {
476	      $relativePath = Get-ManifestRelativePath $_.path $repoRoot
477	      [string]::IsNullOrWhiteSpace($relativePath) -or
478	        $_.sha256 -cnotmatch '^[0-9a-f]{64}$' -or
479	        (-not (Test-AllowedManifestPath $role $relativePath $Stage $FeatureName $contract.attempt $contract.round $calibrationPath) -and
480	         -not ((Test-OrdinalEqual $Stage 'impl') -and $verifiedAdrPaths -ccontains $_.path))
481	    }
482	  }).Count -gt 0
483	  $duplicateManifestPath = $false
484	  foreach ($reviewer in $reviewers) {
485	    $seenPaths = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
486	    foreach ($entry in @($reviewer.allowed_input_manifest)) {
487	      $relativePath = Get-ManifestRelativePath $entry.path $repoRoot
488	      if (-not [string]::IsNullOrWhiteSpace($relativePath) -and -not $seenPaths.Add($relativePath)) { $duplicateManifestPath = $true }
489	    }
490	  }
491	  if ($manifest.Count -eq 0 -or $invalidManifest -or $duplicateManifestPath) { Fail "persisted $Stage contract has an invalid allowed input manifest" }
492	  function Test-ManifestEntry([object]$Reviewer, [string]$ExpectedPath, [string[]]$AllowedHashes) {
493	    foreach ($entry in @($Reviewer.allowed_input_manifest)) {
494	      $relativePath = Get-ManifestRelativePath $entry.path $repoRoot
495	      if (Test-OrdinalEqual $relativePath $ExpectedPath) {
496	        foreach ($allowedHash in $AllowedHashes) {
497	          if (Test-OrdinalEqual $entry.sha256 $allowedHash) { return $true }
498	        }
499	      }
500	    }
501	    return $false
502	  }
503	  $expected = @(
504	    @("specs/$FeatureName/requirements.md", @($RequirementsHash, $RequirementsCurrentHash)),
505	    @("specs/$FeatureName/acceptance-tests.md", @($AcceptanceHash))
506	  )
507	  if ($Stage -eq 'impl') { $expected += ,@("specs/$FeatureName/design.md", @($DesignHash, $DesignCurrentHash)) }
508	  foreach ($reviewer in $reviewers) {
509	    foreach ($pair in $expected) {
510	      if (-not (Test-ManifestEntry $reviewer $pair[0] $pair[1])) { Fail "persisted $Stage contract does not match canonical current inputs for every reviewer" }
511	    }
512	    if (-not (Test-ManifestEntry $reviewer $calibrationPath @($calibrationHash))) { Fail "persisted $Stage contract does not match canonical current inputs for every reviewer" }
513	    $precheckPath = "reports/$Stage-review/$FeatureName/attempt-$($contract.attempt)/round-$($contract.round)/precheck-result.json"
