    }
    $fence = [char]0
    $fenceWidth = 0
    foreach ($rawLine in $text.Split([char]10)) {
        $line = $rawLine
        if ($line.Length -gt 0 -and $line[$line.Length - 1] -ceq [char]13) {
            $line = $line.Substring(0, $line.Length - 1)
        }
        $indent = 0
        while ($indent -lt $line.Length -and $line[$indent] -ceq [char]32) { $indent++ }
