        }
        if ($indent -ge 4 -or $first -ceq [char]9) { continue }
        if ($first -ceq [char]96 -or $first -ceq [char]126) {
            $width = Get-AdrRunWidth $rest 0 $first
            if ($width -ge 3) { $fence = $first; $fenceWidth = $width; continue }
