            $value = $line.Substring($i + $width, $j - $i - $width)
            if ($width -eq 1 -and $value -cmatch '^docs/adr/[0-9]{4}-[a-z0-9][a-z0-9-]*[.]md$') {
                [void]$paths.Add($value)
